:root {
  --bg: #05060d;
  --ink: #eef7ff;
  --muted: #8d9cb5;
  --cyan: #64f5ff;
  --cyan-soft: #b8fbff;
  --magenta: #ff48ae;
  --violet: #9a7cff;
  --lime: #c2ff5b;
  --amber: #ffc35c;
  --line: rgba(167, 205, 255, 0.14);
  --panel: rgba(10, 14, 28, 0.58);
  --display: "Arial Black", "Avenir Next", "Helvetica Neue", Arial, sans-serif;
  --mono: "SFMono-Regular", "Cascadia Code", "Roboto Mono", "DejaVu Sans Mono", Consolas, monospace;
  --pad-x: clamp(18px, 3.6vw, 58px);
  --safe-top: max(16px, env(safe-area-inset-top));
  --safe-bottom: max(14px, env(safe-area-inset-bottom));
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--mono);
  overscroll-behavior: none;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  height: 100dvh;
  min-height: 420px;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(110% 80% at 50% -10%, #0d1834 0%, transparent 56%),
    radial-gradient(80% 60% at 100% 100%, #1b0b21 0%, transparent 60%),
    var(--bg);
}

#game {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: none;
}

.ambient {
  position: absolute;
  z-index: 0;
  width: 55vw;
  height: 55vw;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(90px);
  opacity: 0.18;
  mix-blend-mode: screen;
}

.ambient-a {
  top: -32vw;
  left: -18vw;
  background: #0fd9ff;
  animation: ambient-drift-a 20s ease-in-out infinite alternate;
}

.ambient-b {
  right: -20vw;
  bottom: -34vw;
  background: #f2238b;
  animation: ambient-drift-b 24s ease-in-out infinite alternate;
}

@keyframes ambient-drift-a {
  to { transform: translate3d(8vw, 6vw, 0) scale(1.12); }
}

@keyframes ambient-drift-b {
  to { transform: translate3d(-7vw, -4vw, 0) scale(1.08); }
}

.grain,
.scanlines {
  position: absolute;
  inset: 0;
  z-index: 30;
  pointer-events: none;
}

.grain {
  opacity: 0.055;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.85'/%3E%3C/svg%3E");
}

.scanlines {
  opacity: 0.18;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 3px,
    rgba(0, 0, 0, 0.26) 3px,
    rgba(0, 0, 0, 0.26) 4px
  );
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.9), transparent 75%);
}

/* ── Top HUD ─────────────────────────────────────────────── */

.topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: grid;
  grid-template-columns: minmax(150px, 1fr) auto minmax(150px, 1fr);
  align-items: center;
  gap: 20px;
  padding: calc(var(--safe-top) + 4px) var(--pad-x) 0;
  pointer-events: none;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  width: max-content;
  color: var(--ink);
  text-decoration: none;
  pointer-events: auto;
}

.brand-glyph {
  position: relative;
  display: flex;
  align-items: flex-end;
  gap: 3px;
  width: 24px;
  height: 28px;
  transform: skewX(-17deg);
}

.brand-glyph i {
  display: block;
  width: 5px;
  border-radius: 1px;
  background: var(--cyan);
  box-shadow: 0 0 12px rgba(100, 245, 255, 0.5);
}

.brand-glyph i:nth-child(1) { height: 13px; opacity: 0.55; }
.brand-glyph i:nth-child(2) { height: 21px; }
.brand-glyph i:nth-child(3) { height: 28px; background: var(--magenta); box-shadow: 0 0 12px rgba(255, 72, 174, 0.5); }

.brand-word {
  font-family: var(--display);
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.13em;
  line-height: 1;
  white-space: nowrap;
}

.brand-slash {
  color: var(--magenta);
  padding: 0 1px;
}

.telemetry {
  display: flex;
  align-items: stretch;
  min-height: 46px;
  padding: 7px 10px;
  border: 1px solid rgba(166, 204, 255, 0.12);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(12, 17, 34, 0.62), rgba(6, 9, 20, 0.3));
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(12px);
}

.stat {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 76px;
  padding: 0 14px;
}

.stat + .stat::before {
  position: absolute;
  top: 4px;
  bottom: 4px;
  left: 0;
  width: 1px;
  content: "";
  background: rgba(150, 190, 255, 0.1);
}

.stat-label {
  color: #8794ad;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.22em;
  line-height: 1;
  white-space: nowrap;
}

.stat strong {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 5px;
  color: #f1f8ff;
  font-size: 14px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.06em;
  line-height: 1;
}

.stat strong em {
  color: #5e6b85;
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0;
}

.stat-score strong {
  color: var(--cyan-soft);
  text-shadow: 0 0 16px rgba(100, 245, 255, 0.28);
}

.stat-swarm {
  min-width: 92px;
}

.swarm-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--magenta);
  box-shadow: 0 0 8px var(--magenta);
  transition: transform 0.16s ease;
}

.swarm-dot.pop {
  transform: scale(2.2);
}

.swarm-track {
  position: absolute;
  right: 14px;
  bottom: 7px;
  left: 14px;
  height: 2px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.08);
}

.swarm-track i {
  display: block;
  width: 7%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--cyan), var(--magenta));
  box-shadow: 0 0 8px rgba(255, 72, 174, 0.65);
  transition: width 0.24s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.stat-cores {
  padding-right: 10px;
}

#cores {
  gap: 4px;
}

.core-pip {
  display: block;
  width: 8px;
  height: 8px;
  border: 1px solid rgba(100, 245, 255, 0.9);
  background: rgba(100, 245, 255, 0.28);
  box-shadow: 0 0 7px rgba(100, 245, 255, 0.32);
  transform: rotate(45deg);
}

.core-pip.lost {
  border-color: rgba(120, 135, 160, 0.24);
  background: transparent;
  box-shadow: none;
}

.utilities {
  display: flex;
  align-items: center;
  justify-self: end;
  gap: 7px;
  pointer-events: auto;
}

.icon-btn {
  display: grid;
  width: 37px;
  height: 37px;
  padding: 0;
  border: 1px solid rgba(167, 205, 255, 0.14);
  border-radius: 9px;
  place-items: center;
  background: rgba(9, 13, 27, 0.46);
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
  backdrop-filter: blur(10px);
}

.icon-btn:hover {
  border-color: rgba(100, 245, 255, 0.48);
  background: rgba(23, 35, 58, 0.7);
}

.icon-btn:active {
  transform: scale(0.93);
}

.icon-btn svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: #b8c7dd;
  stroke-width: 1.6;
  stroke-linecap: round;
}

.icon-btn .sound-off {
  display: none;
}

.icon-btn.muted .sound-on {
  display: none;
}

.icon-btn.muted .sound-off {
  display: block;
}

/* ── Gameplay overlays ───────────────────────────────────── */

.combo {
  position: absolute;
  top: calc(var(--safe-top) + 82px);
  left: var(--pad-x);
  z-index: 9;
  display: flex;
  align-items: baseline;
  gap: 7px;
  color: var(--magenta);
  text-shadow: 0 0 20px rgba(255, 72, 174, 0.42);
  opacity: 0;
  pointer-events: none;
  transform: translateY(6px);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.combo.active {
  opacity: 1;
  transform: translateY(0);
}

.combo span {
  color: #8794ad;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.22em;
}

.combo strong {
  font-family: var(--display);
  font-size: 23px;
  font-style: italic;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.combo.bump strong {
  animation: combo-bump 0.18s cubic-bezier(0.2, 0.9, 0.2, 1.4);
}

@keyframes combo-bump {
  50% { transform: scale(1.35) rotate(-3deg); }
}

.edge {
  position: absolute;
  z-index: 2;
  top: 16%;
  bottom: 12%;
  width: 1px;
  pointer-events: none;
  background: linear-gradient(to bottom, transparent, rgba(100, 245, 255, 0.2) 22%, rgba(100, 245, 255, 0.2) 78%, transparent);
  box-shadow: 0 0 20px rgba(100, 245, 255, 0.08);
}

.edge-left { left: var(--pad-x); }
.edge-right { right: var(--pad-x); }

.bottombar {
  position: absolute;
  right: var(--pad-x);
  bottom: calc(var(--safe-bottom) + 3px);
  left: var(--pad-x);
  z-index: 8;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  pointer-events: none;
}

.control-hint,
.split-readout {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #66748f;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

kbd {
  display: inline-flex;
  min-width: 21px;
  height: 19px;
  padding: 0 5px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(167, 205, 255, 0.22);
  border-bottom-color: rgba(167, 205, 255, 0.12);
  border-radius: 4px;
  background: rgba(15, 22, 41, 0.8);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  color: #b6c5db;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
}

.hint-divider {
  width: 1px;
  height: 10px;
  margin: 0 2px;
  background: rgba(167, 205, 255, 0.14);
}

.touch-hint { display: none; }

.split-readout {
  justify-content: flex-end;
  color: #596783;
  text-align: right;
}

.split-pulse {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--magenta);
  box-shadow: 0 0 10px var(--magenta);
  animation: pulse-dot 2.2s ease-in-out infinite;
}

@keyframes pulse-dot {
  50% { opacity: 0.35; transform: scale(0.7); }
}

.split-cap {
  margin-left: 5px;
  padding: 3px 5px;
  border: 1px solid rgba(255, 72, 174, 0.18);
  border-radius: 3px;
  color: #9d5b83;
  font-size: 7px;
  letter-spacing: 0.12em;
}

.announcer {
  position: absolute;
  top: 20%;
  left: 50%;
  z-index: 12;
  padding: 8px 14px;
  border: 1px solid rgba(100, 245, 255, 0.26);
  border-radius: 99px;
  background: rgba(8, 14, 29, 0.75);
  box-shadow: 0 0 30px rgba(100, 245, 255, 0.1);
  color: var(--cyan-soft);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  opacity: 0;
  pointer-events: none;
  text-transform: uppercase;
  transform: translate(-50%, 8px);
  transition: opacity 0.22s ease, transform 0.22s ease;
  backdrop-filter: blur(10px);
  white-space: nowrap;
}

.announcer.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ── Intro / title screen ────────────────────────────────── */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  padding: calc(var(--safe-top) + 76px) var(--pad-x) calc(var(--safe-bottom) + 54px);
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  text-align: center;
}

[hidden] {
  display: none !important;
}

.intro-overlay {
  background:
    radial-gradient(ellipse 46% 46% at 50% 43%, rgba(7, 12, 29, 0.82) 0%, rgba(5, 7, 16, 0.42) 52%, transparent 78%),
    linear-gradient(180deg, rgba(5, 6, 13, 0.34), transparent 28%, transparent 70%, rgba(5, 6, 13, 0.5));
}

.intro-overlay::before {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(70vw, 900px);
  height: min(32vw, 360px);
  border: 1px solid rgba(100, 245, 255, 0.08);
  border-radius: 50%;
  content: "";
  filter: blur(0.2px);
  pointer-events: none;
  transform: translate(-50%, -50%) rotate(-8deg);
}

.intro-orbit {
  position: absolute;
  top: 48%;
  left: 50%;
  width: min(62vw, 820px);
  aspect-ratio: 1;
  pointer-events: none;
  transform: translate(-50%, -50%);
}

.orbit {
  position: absolute;
  inset: 10%;
  border: 1px solid rgba(127, 174, 255, 0.075);
  border-radius: 50%;
}

.orbit-a {
  border-top-color: rgba(100, 245, 255, 0.24);
  border-right-color: rgba(100, 245, 255, 0.04);
  transform: rotate(24deg) scaleY(0.46);
  animation: orbit-spin 28s linear infinite;
}

.orbit-b {
  inset: 18%;
  border-bottom-color: rgba(255, 72, 174, 0.26);
  border-left-color: rgba(255, 72, 174, 0.04);
  transform: rotate(-38deg) scaleY(0.62);
  animation: orbit-spin-reverse 20s linear infinite;
}

.orbit-c {
  inset: 27%;
  border-style: dashed;
  border-color: rgba(154, 124, 255, 0.06);
  transform: rotate(8deg) scaleY(0.38);
}

@keyframes orbit-spin {
  to { transform: rotate(384deg) scaleY(0.46); }
}

@keyframes orbit-spin-reverse {
  to { transform: rotate(-398deg) scaleY(0.62); }
}

.eyebrow {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 0 0 17px;
  color: #7d8ba6;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.3em;
  line-height: 1;
  text-transform: uppercase;
}

.eyebrow i {
  width: 34px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(100, 245, 255, 0.6), transparent);
}

.intro-overlay .eyebrow span:last-child {
  color: var(--cyan);
}

h1,
h2 {
  position: relative;
  z-index: 1;
  margin: 0;
  font-family: var(--display);
  font-weight: 900;
  line-height: 0.82;
  letter-spacing: -0.055em;
  text-transform: uppercase;
}

h1 {
  font-size: clamp(3rem, 10.6vw, 8.65rem);
  white-space: nowrap;
  background: linear-gradient(180deg, #ffffff 0%, #dffaff 46%, #8eb7d7 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 12px 32px rgba(0, 0, 0, 0.42)) drop-shadow(0 0 30px rgba(100, 245, 255, 0.1));
}

h1::after {
  position: absolute;
  right: -0.03em;
  bottom: -0.18em;
  left: 0;
  height: 0.035em;
  content: "";
  background: linear-gradient(90deg, transparent, rgba(100, 245, 255, 0.7) 18%, rgba(255, 72, 174, 0.8) 82%, transparent);
  filter: blur(0.5px);
  opacity: 0.6;
}

h1 span {
  display: inline-block;
  margin: 0 0.015em;
  color: var(--magenta);
  -webkit-text-fill-color: transparent;
  background: linear-gradient(180deg, #ffd6eb 0%, #ff48ae 52%, #9e1d67 100%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 18px rgba(255, 72, 174, 0.38));
  transform: skewX(-8deg);
}

.tagline {
  position: relative;
  z-index: 1;
  margin: 26px 0 0;
  color: #7e8ba3;
  font-size: clamp(10px, 1.1vw, 12px);
  font-weight: 500;
  letter-spacing: 0.055em;
  line-height: 1.7;
}

.tagline strong {
  color: #cbd9eb;
  font-weight: 700;
}

.intro-actions {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 24px;
  margin-top: 27px;
}

.primary-btn {
  position: relative;
  display: inline-flex;
  min-width: 144px;
  height: 48px;
  padding: 0 18px 0 23px;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  overflow: hidden;
  border: 0;
  border-radius: 7px;
  background: linear-gradient(105deg, #f5ffff 0%, #bdf9ff 100%);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.45) inset,
    0 12px 38px rgba(64, 226, 255, 0.16),
    0 0 0 6px rgba(100, 245, 255, 0.035);
  color: #071018;
  cursor: pointer;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  transition: transform 0.18s cubic-bezier(0.2, 0.9, 0.2, 1), box-shadow 0.18s ease;
}

.primary-btn::before {
  position: absolute;
  top: 0;
  left: -40%;
  width: 28%;
  height: 100%;
  content: "";
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.85), transparent);
  transform: skewX(-20deg);
  transition: left 0.46s ease;
}

.primary-btn:hover {
  box-shadow:
    0 0 0 1px #ffffff inset,
    0 15px 48px rgba(64, 226, 255, 0.27),
    0 0 0 7px rgba(100, 245, 255, 0.06);
  transform: translateY(-2px);
}

.primary-btn:hover::before {
  left: 118%;
}

.primary-btn:active {
  transform: translateY(0) scale(0.98);
}

.primary-btn:focus-visible,
.ghost-btn:focus-visible,
.icon-btn:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

.primary-btn svg {
  width: 15px;
  height: 15px;
  fill: #071018;
  stroke: none;
}

.best-score {
  display: flex;
  min-width: 100px;
  padding-left: 22px;
  border-left: 1px solid rgba(167, 205, 255, 0.16);
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  text-align: left;
}

.best-score span {
  color: #68758d;
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.18em;
  white-space: nowrap;
}

.best-score strong {
  color: #c4d2e6;
  font-size: 13px;
