function makeBrickSprite(brick) {
  const color = COLORS[brick.colorIndex];
  const pad = 9;
  const dpr = state.dpr;
  const sprite = document.createElement('canvas');
  sprite.width = Math.max(1, Math.ceil((brick.w + pad * 2) * dpr));
  sprite.height = Math.max(1, Math.ceil((brick.h + pad * 2) * dpr));
  const context = sprite.getContext('2d');
  context.scale(dpr, dpr);
  const x = pad;
  const y = pad;
  const radius = 3.5;

  context.save();
  context.shadowColor = rgba(color.rgb, 0.34);
  context.shadowBlur = 7;
  roundRectPath(context, x, y, brick.w, brick.h, radius);
  context.fillStyle = brick.gradient;
  context.fill();
  context.shadowBlur = 0;
  context.strokeStyle = rgba(color.rgb, 0.58);
  context.lineWidth = 1;
  context.stroke();

  context.save();
  roundRectPath(context, x, y, brick.w, brick.h, radius);
  context.clip();
  const gloss = context.createLinearGradient(0, y, 0, y + brick.h);
  gloss.addColorStop(0, 'rgba(255, 255, 255, 0.25)');
  gloss.addColorStop(0.28, 'rgba(255, 255, 255, 0.03)');
  gloss.addColorStop(0.7, 'rgba(3, 7, 15, 0.02)');
  gloss.addColorStop(1, 'rgba(3, 7, 15, 0.44)');
  context.fillStyle = gloss;
  context.fillRect(x, y, brick.w, brick.h);

  context.fillStyle = 'rgba(255, 255, 255, 0.29)';
  context.fillRect(x + brick.w * 0.1, y + 1.5, brick.w * 0.8, 1);
  context.fillStyle = 'rgba(3, 8, 18, 0.28)';
  context.fillRect(x + brick.w * 0.12, y + brick.h - 2.4, brick.w * 0.76, 1);

  if (brick.maxHp > 1) {
    context.fillStyle = 'rgba(255, 255, 255, 0.66)';
    context.fillRect(x + brick.w - 7, y + 3.5, 2.5, 2.5);
    context.strokeStyle = 'rgba(255, 255, 255, 0.24)';
    context.strokeRect(x + 4.5, y + 4, brick.w - 9, brick.h - 8);
  }

  if (brick.hp < brick.maxHp) {
    context.strokeStyle = 'rgba(3, 7, 15, 0.58)';
    context.lineWidth = 1;
    context.beginPath();
    for (const crack of brick.cracks) {
      const cx = x + crack.x * brick.w;
      const cy = y + crack.y * brick.h;
      context.moveTo(cx, cy);
      context.lineTo(cx + crack.dx * brick.w, cy + crack.dy * brick.h);
      context.lineTo(cx + crack.dx * brick.w + brick.w * 0.08, cy + crack.dy * brick.h + brick.h * 0.2);
    }
    context.stroke();
    context.strokeStyle = 'rgba(255, 255, 255, 0.22)';
    context.lineWidth = 0.6;
    context.stroke();
  }
  context.restore();
  context.restore();

  return { canvas: sprite, pad, width: brick.w + pad * 2, height: brick.h + pad * 2 };
}

