function drawBricks() {
  const alpha = state.mode === 'menu' ? 0.34 : 1;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const color = COLORS[brick.colorIndex];
    const jitterX = brick.flash > 0 ? random(-1, 1) * brick.flash : 0;
    const jitterY = brick.flash > 0 ? random(-1, 1) * brick.flash : 0;
    const x = brick.x + jitterX;
    const y = brick.y + jitterY;
    const radius = 3.5;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.shadowColor = rgba(color.rgb, 0.22);
    ctx.shadowBlur = brick.flash > 0 ? 18 : 7;
    roundRectPath(ctx, x, y, brick.w, brick.h, radius);
    ctx.fillStyle = brick.gradient;
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = rgba(color.rgb, 0.52);
    ctx.lineWidth = 1;
    ctx.stroke();

    roundRectPath(ctx, x, y, brick.w, brick.h, radius);
    ctx.clip();
    const gloss = ctx.createLinearGradient(0, y, 0, y + brick.h);
    gloss.addColorStop(0, 'rgba(255, 255, 255, 0.24)');
    gloss.addColorStop(0.28, 'rgba(255, 255, 255, 0.03)');
    gloss.addColorStop(0.7, 'rgba(3, 7, 15, 0.02)');
    gloss.addColorStop(1, 'rgba(3, 7, 15, 0.44)');
    ctx.fillStyle = gloss;
    ctx.fillRect(x, y, brick.w, brick.h);

    ctx.fillStyle = 'rgba(255, 255, 255, 0.27)';
    ctx.fillRect(x + brick.w * 0.1, y + 1.5, brick.w * 0.8, 1);

    ctx.fillStyle = 'rgba(3, 8, 18, 0.28)';
    ctx.fillRect(x + brick.w * 0.12, y + brick.h - 2.4, brick.w * 0.76, 1);

    if (brick.maxHp > 1) {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.62)';
      ctx.fillRect(x + brick.w - 7, y + 3.5, 2.5, 2.5);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.24)';
      ctx.strokeRect(x + 4.5, y + 4, brick.w - 9, brick.h - 8);
    }

    if (brick.hp < brick.maxHp) {
      ctx.strokeStyle = 'rgba(3, 7, 15, 0.55)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (const crack of brick.cracks) {
        const cx = x + crack.x * brick.w;
        const cy = y + crack.y * brick.h;
        ctx.moveTo(cx, cy);
        ctx.lineTo(cx + crack.dx * brick.w, cy + crack.dy * brick.h);
        ctx.lineTo(cx + crack.dx * brick.w + brick.w * 0.08, cy + crack.dy * brick.h + brick.h * 0.2);
      }
      ctx.stroke();
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.24)';
      ctx.lineWidth = 0.6;
      ctx.stroke();
    }

    if (brick.flash > 0) {
      ctx.fillStyle = `rgba(255, 255, 255, ${(brick.flash * 0.48).toFixed(3)})`;
      ctx.fillRect(x, y, brick.w, brick.h);
    }
    ctx.restore();
  }
}

