function render() {
  const width = state.width;
  const height = state.height;
  ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.clearRect(0, 0, width, height);

  const shakeX = state.shake > 0 ? random(-state.shake, state.shake) : 0;
  const shakeY = state.shake > 0 ? random(-state.shake, state.shake) : 0;

  ctx.save();
  ctx.translate(shakeX, shakeY);
  drawBackground();
  drawBricks();
  drawRings();
  drawPaddle();
  drawBalls();
  drawParticles();
  drawScoreText();
  ctx.restore();
}

function drawBackground() {
  const { width, height, wall } = state;
  const step = Math.max(48, Math.round(width / 20));
  ctx.save();
  ctx.strokeStyle = state.gridGradient;
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = wall.left + step; x < wall.right; x += step) {
    ctx.moveTo(x, wall.top);
    ctx.lineTo(x, wall.bottom);
  }
  for (let y = wall.top + step; y < wall.bottom; y += step) {
    ctx.moveTo(wall.left, y);
    ctx.lineTo(wall.right, y);
  }
  ctx.stroke();
  ctx.restore();

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const star of state.stars) {
    const twinkle = 0.42 + 0.58 * Math.sin(state.time * star.speed + star.phase);
    const alpha = star.alpha * twinkle;
    ctx.fillStyle = `rgba(190, 225, 255, ${alpha.toFixed(3)})`;
    const x = (star.x + state.time * star.drift) % (width + 20) - 10;
    ctx.fillRect(x, star.y, star.size, star.size);
  }
  ctx.restore();

  const danger = ctx.createLinearGradient(0, height - 110, 0, height);
  danger.addColorStop(0, 'rgba(255, 72, 174, 0)');
  danger.addColorStop(0.7, 'rgba(255, 72, 174, 0.025)');
  danger.addColorStop(1, 'rgba(255, 72, 174, 0.075)');
  ctx.fillStyle = danger;
  ctx.fillRect(wall.left, height - 110, wall.right - wall.left, 110);

