  document.addEventListener('visibilitychange', () => {
    if (document.hidden && state.mode === 'playing') togglePause();
  });

  window.addEventListener('pointerdown', initAudio, { once: true, passive: true });
  window.addEventListener('keydown', initAudio, { once: true });

  let resizeFrame = 0;
  function scheduleResize() {
    window.cancelAnimationFrame(resizeFrame);
    resizeFrame = window.requestAnimationFrame(() => {
      resizeGame();
      updateHUD();
    });
  }
  window.addEventListener('resize', scheduleResize);
  if (window.visualViewport) window.visualViewport.addEventListener('resize', scheduleResize);

  function loop(now) {
    const elapsed = Math.max(0, Math.min(0.05, (now - state.last) / 1000));
    state.last = now;
    update(elapsed);
    render();
    window.requestAnimationFrame(loop);
  }

  function init() {
    applyMute();
    dom.bestIntro.textContent = String(state.best).padStart(6, '0');
    resizeGame();
    state.paddle.x = state.width / 2;
    state.paddle.targetX = state.width / 2;
    buildBricks();
    refreshCombo();
    updateHUD();
    window.requestAnimationFrame(loop);
  }

  init();
})();

