const { createRequire } = require('module');
const { readFileSync } = require('fs');
const { join } = require('path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const variants = {
  normal: '',
  noAfter: '#app::after{display:none!important}',
  noAmbient: '.ambient{display:none!important}',
  noIntro: '.intro-overlay{display:none!important}',
  noAfterAmbient: '#app::after{display:none!important}.ambient{display:none!important}',
  noFlash: '.damage-flash{display:none!important}',
  noEdges: '.edge{display:none!important}.bottombar{display:none!important}.combo{display:none!important}',
  noHud: '.topbar,.edge,.bottombar,.combo,.announcer,.level-banner,.toast{display:none!important}',
  noOverlaysNoAfter: '.intro-overlay,#app::after,.ambient,.damage-flash{display:none!important}',
  noAnim: '*{animation:none!important;transition:none!important}',
  noTextClip: 'h1,h1 span{-webkit-background-clip:border-box!important;background-clip:border-box!important;color:#fff!important;-webkit-text-fill-color:#fff!important;background:none!important}',
};

async function measure(page, play) {
  if (play) {
    await page.click('#play-btn').catch(() => {});
    await page.waitForTimeout(1200);
  } else {
    await page.waitForTimeout(2200);
  }
  return page.evaluate(() => new Promise(res => {
    let f = 0; const s = performance.now();
    function t() { f++; if (performance.now() - s < 1600) requestAnimationFrame(t); else res(f / ((performance.now() - s) / 1000)); }
    requestAnimationFrame(t);
  }));
}

async function run(browser, css, play) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  if (css !== null) {
    const base = readFileSync('/home/runner/work/PlayGround/PlayGround/styles.css', 'utf8');
    await page.route('**/styles.css', r => r.fulfill({ status: 200, contentType: 'text/css', body: base + '\n' + css }));
  } else {
    await page.route('**/styles.css', r => r.abort());
  }
  await page.goto('http://localhost:3002/', { waitUntil: 'load' }).catch(() => {});
  const fps = await measure(page, play);
  await page.close();
  return fps;
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const names = process.argv.slice(2);
  const list = names.length ? names : Object.keys(variants);
  for (const name of list) {
    const css = variants[name];
    const fps = await run(browser, css, false);
    const fpsPlay = await run(browser, css, true);
    console.log(name.padEnd(22), 'intro', fps.toFixed(1), ' play', fpsPlay.toFixed(1));
  }
  await browser.close();
})();

