const { createRequire } = require('module');
const { readFileSync } = require('fs');
const { join } = require('path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

async function run(browser, setup) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'load' }).catch(() => {});
  await page.waitForTimeout(1500);
  if (setup) await page.evaluate(setup);
  await page.waitForTimeout(800);
  const out = await page.evaluate(() => new Promise(res => {
    let f = 0; const s = performance.now();
    function t() { f++; if (performance.now() - s < 1600) requestAnimationFrame(t); else res({
      fps: f / ((performance.now() - s) / 1000),
      cw: document.querySelector('#game').width,
      ch: document.querySelector('#game').height,
      rect: document.querySelector('#game').getBoundingClientRect().toJSON(),
      work: window.__lastFrameWork,
      dpr: window.devicePixelRatio,
    }); }
    requestAnimationFrame(t);
  }));
  await page.close();
  return out;
}

const setups = {
  base: null,
  noRender: () => { window.__splitRender = false; },
  hideCanvas: () => { document.querySelector('#game').style.display = 'none'; },
  tinyCanvasCss: () => { const g = document.querySelector('#game'); g.style.width = '300px'; g.style.height = '150px'; },
  noShake: () => { window.__splitDebug.state.shake = 0; },
  noCSSLayer: () => { document.querySelector('#app').style.isolation = 'auto'; },
};

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const names = process.argv.slice(2);
  for (const name of (names.length ? names : Object.keys(setups))) {
    const o = await run(browser, setups[name]);
    console.log(name.padEnd(16), JSON.stringify(o));
  }
  await browser.close();
})();

