async function run(browser, mode, target) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'load' }).catch(() => {});
  await page.waitForTimeout(1200);
  await page.evaluate(([mode, target]) => {
    if (mode === 'only') {
      window.__splitLayers = {};
      for (const k of ['bg', 'bricks', 'rings', 'paddle', 'balls', 'particles', 'text']) window.__splitLayers[k] = k === target;
    } else if (target) {
      window.__splitLayers = { [target]: false };
    }
  }, [mode, target]);
  await page.waitForTimeout(500);
  const fps = await page.evaluate(() => new Promise(res => {
    let f = 0; const s = performance.now();
    function t() { f++; if (performance.now() - s < 1500) requestAnimationFrame(t); else res(f / ((performance.now() - s) / 1000)); }
    requestAnimationFrame(t);
  }));
  await page.close();
  return fps;
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  for (const [name, mode, target] of cases) {
    console.log(name.padEnd(16), (await run(browser, mode, target)).toFixed(1));
  }
  await browser.close();
})();

