const { readFileSync } = require('fs');
const { join } = require('path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const base = readFileSync('/home/runner/work/PlayGround/PlayGround/styles.css', 'utf8');

const variants = {
  normal: '',
  pixelated: '#game{image-rendering:pixelated}',
  crispEdges: '#game{image-rendering:crisp-edges}',
  pixelSize: '#game{width:893px!important;height:558px!important;left:50%!important;top:50%!important;transform:translate(-50%,-50%)}',
  scaled1: '#game{image-rendering:pixelated}.intro-overlay,.ambient,#app::after{display:none!important}',
};

async function run(browser, css) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.route('**/styles.css', r => r.fulfill({ status: 200, contentType: 'text/css', body: base + '\n' + css }));
  await page.goto('http://localhost:3002/', { waitUntil: 'load' }).catch(() => {});
  await page.waitForTimeout(1800);
  await page.evaluate(() => { window.__splitLayers = { bg: false, bricks: false, rings: false, paddle: false, balls: false, particles: false, text: false }; });
  await page.waitForTimeout(500);
  const fps = await page.evaluate(() => new Promise(res => {
    let f = 0; const s = performance.now();
    function t() { f++; if (performance.now() - s < 1600) requestAnimationFrame(t); else res(f / ((performance.now() - s) / 1000)); }
    requestAnimationFrame(t);
  }));
  await page.close();
  return fps;
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  for (const name of Object.keys(variants)) console.log(name.padEnd(14), (await run(browser, variants[name])).toFixed(1));
  await browser.close();
})();

