const { createRequire } = require('module');
const { readFileSync } = require('fs');
const { join } = require('path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const base = readFileSync('/home/runner/work/PlayGround/PlayGround/styles.css', 'utf8');

const variants = {
  normal: '',
  cssUp: '#game{width:893px!important;height:558px!important;transform:scale(1.6126);transform-origin:0 0;image-rendering:auto}',
  cssUpPixel: '#game{width:893px!important;height:558px!important;transform:scale(1.6126);transform-origin:0 0;image-rendering:pixelated}',
  cssUpScene: '#app{width:893px!important;height:558px!important;transform:scale(1.6126);transform-origin:0 0}',
};

async function run(browser, css, play) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.route('**/styles.css', r => r.fulfill({ status: 200, contentType: 'text/css', body: base + '\n' + css }));
  await page.goto('http://localhost:3002/', { waitUntil: 'load' }).catch(() => {});
  await page.waitForTimeout(1800);
  if (play) { await page.click('#play-btn').catch(() => {}); await page.waitForTimeout(1200); }
  const fps = await page.evaluate(() => new Promise(res => {
    let f = 0; const s = performance.now();
    function t() { f++; if (performance.now() - s < 1600) requestAnimationFrame(t); else res(f / ((performance.now() - s) / 1000)); }
    requestAnimationFrame(t);
  }));
  await page.close();
  return fps;
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  for (const name of Object.keys(variants)) console.log(name.padEnd(14), 'intro', (await run(browser, variants[name], false)).toFixed(1), 'play', (await run(browser, variants[name], true)).toFixed(1));
  await browser.close();
})();

