const { createRequire } = require('module');
const { readFileSync } = require('fs');
const { join } = require('path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const src = readFileSync('/home/runner/work/PlayGround/PlayGround/game.js', 'utf8');

const variants = {
  normal: s => s,
  noShadow: s => s.replace('ctx.shadowBlur = 16 + paddle.flash * 18;', 'ctx.shadowBlur = 0;'),
  noTrail: s => s.replace('for (let index = 0; index < ball.trail.length; index += 1) {', 'for (let index = 0; index < 0; index += 1) {'),
  noStars: s => s.replace('for (const star of state.stars) {', 'for (const star of []) {'),
  noGrid: s => s.replace('for (let x = wall.left + step; x < wall.right; x += step) {', 'for (let x = wall.left + step; x < wall.left; x += step) {'),
  noGlowPaddle: s => s.replace("ctx.fillRect(x - paddle.w * 0.2, y - paddle.h * 1.2, paddle.w * 1.4, paddle.h * 3.1);", ''),
  noUnder: s => s.replace("ctx.fillRect(paddle.x - paddle.w * 0.36, y + paddle.h, paddle.w * 0.72, 18);", ''),
  noAllEffects: s => variants.noShadow(variants.noTrail(variants.noStars(variants.noGrid(variants.noGlowPaddle(variants.noUnder(s)))))),
};

async function run(browser, transform, play) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const body = transform(src);
  await page.route('**/game.js', r => r.fulfill({ status: 200, contentType: 'application/javascript', body }));
  await page.goto('http://localhost:3002/', { waitUntil: 'load' }).catch(() => {});
  await page.waitForTimeout(1600);
  if (play) { await page.click('#play-btn').catch(() => {}); await page.waitForTimeout(1200); }
  const fps = await page.evaluate(() => new Promise(res => {
    let f = 0; const s = performance.now();
    function t() { f++; if (performance.now() - s < 1600) requestAnimationFrame(t); else res(f / ((performance.now() - s) / 1000)); }
    requestAnimationFrame(t);
  }));
  await page.close();
  return fps;
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  for (const name of Object.keys(variants)) {
    const f = await run(browser, variants[name], true);
    console.log(name.padEnd(14), f.toFixed(1));
  }
  await browser.close();
})();

