const { createRequire } = require('module');
const { readFileSync } = require('fs');
const { join } = require('path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';

async function start(page, url) {
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto(url, { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  return errors;
}

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const url = 'http://localhost:3002/';

  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = await start(page, url);
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${OUT}/verify-intro.png` });
  const introVisible = await page.locator('#intro').isVisible();
  console.log('intro visible:', introVisible);

  await page.click('#play-btn');
  await page.waitForTimeout(1400);
  await page.mouse.move(720, 780);
  await page.keyboard.press('Space');
  await page.waitForTimeout(6500);
  await page.mouse.move(620, 780);
  await page.waitForTimeout(900);
  const hud = await page.evaluate(() => ({
    score: document.querySelector('#score').textContent,
    balls: document.querySelector('#balls').textContent,
    level: document.querySelector('#level').textContent,
    introHidden: document.querySelector('#intro').hidden,
    swarm: document.querySelector('#swarm-fill').style.width,
    comboActive: document.querySelector('#combo').classList.contains('active'),
  }));
  console.log('hud:', JSON.stringify(hud));
  await page.screenshot({ path: `${OUT}/verify-play.png` });

  await page.keyboard.press('KeyP');
  await page.waitForTimeout(500);
  console.log('pause visible:', await page.locator('#pause').isVisible());
  await page.screenshot({ path: `${OUT}/verify-pause.png` });
  await page.keyboard.press('KeyP');
  await page.waitForTimeout(300);
  console.log('pause hidden after resume:', !(await page.locator('#pause').isVisible()));

  // Resize responsiveness
  await page.setViewportSize({ width: 1024, height: 640 });
  await page.waitForTimeout(700);
  await page.screenshot({ path: `${OUT}/verify-1024.png` });

  console.log('desktop errors:', errors.length ? errors : 'none');
  await page.close();

  // Mobile with touch
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  const mErrors = await start(mobile, url);
  await mobile.waitForTimeout(1200);
  await mobile.screenshot({ path: `${OUT}/verify-mobile-intro.png` });
  await mobile.tap('#play-btn');
  await mobile.waitForTimeout(1300);
  await mobile.touchscreen.tap(195, 700);
  await mobile.waitForTimeout(5000);
  const mHud = await mobile.evaluate(() => ({
    score: document.querySelector('#score').textContent,
    balls: document.querySelector('#balls').textContent,
    introHidden: document.querySelector('#intro').hidden,
    overflowX: document.documentElement.scrollWidth > window.innerWidth,
  }));
  console.log('mobile hud:', JSON.stringify(mHud));
  await mobile.screenshot({ path: `${OUT}/verify-mobile-play.png` });
  console.log('mobile errors:', mErrors.length ? mErrors : 'none');
  await mobile.close();

  await browser.close();
})();

