const { createRequire } = require('module');
const { readFileSync } = require('fs');
const { join } = require('path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const page = await browser.newPage({ viewport: { width: 844, height: 390 } });
  await page.goto('http://localhost:3002/', { waitUntil: 'load' });
  await page.waitForTimeout(800);
  const info = await page.evaluate(() => {
    const intro = document.querySelector('#intro');
    const cs = getComputedStyle(intro);
    const out = { intro: { client: intro.clientHeight, scroll: intro.scrollHeight, justify: cs.justifyContent, padding: cs.padding, gap: cs.gap } };
    for (const el of intro.children) {
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      out[el.className || el.tagName] = {
        h: Math.round(r.height), top: Math.round(r.top), bottom: Math.round(r.bottom),
        mt: s.marginTop, mb: s.marginBottom, display: s.display, fs: s.fontSize,
      };
    }
    return out;
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();

