const { createRequire } = require('module');
const { readFileSync } = require('fs');
const { join } = require('path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const src = readFileSync('/home/runner/work/PlayGround/PlayGround/game.js', 'utf8');
const patched = src.replace('  init();\n})();', '  window.__testEnd = () => { state.lives = 0; endGame(); };\n  init();\n})();');

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height } });
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.route('**/game.js', r => r.fulfill({ status: 200, contentType: 'application/javascript', body: patched }));
    await page.goto('http://localhost:3002/', { waitUntil: 'load' });
    await page.waitForTimeout(700);
    await page.click('#play-btn');
    await page.waitForTimeout(2200);
    await page.evaluate(() => window.__testEnd());
    await page.waitForTimeout(500);
    const state = await page.evaluate(() => ({
      gameover: !document.querySelector('#gameover').hidden,
      note: document.querySelector('#result-note').textContent,
      score: document.querySelector('#final-score').textContent,
    }));
    console.log(name, JSON.stringify(state));
    await page.screenshot({ path: `${OUT}/verify-gameover-${name}.png` });
    await page.click('#menu-btn');
    await page.waitForTimeout(500);
    console.log(name, 'menu:', await page.locator('#intro').isVisible(), 'gameover hidden:', await page.evaluate(() => document.querySelector('#gameover').hidden));
    await page.click('#play-btn');
    await page.waitForTimeout(500);
    console.log(name, 'restart:', await page.evaluate(() => ({
      overHidden: document.querySelector('#gameover').hidden,
      score: document.querySelector('#score').textContent,
      lives: document.querySelectorAll('.core-pip:not(.lost)').length,
      pauseDisabled: document.querySelector('#pause-btn').disabled,
    })));
    console.log(name, 'errors:', errors.length ? errors : 'none');
    await page.close();
  }
  await browser.close();
})();

